        var adj: [Int: [[Int]]] = [:]
        for i in 0..<N {
            let x1 = points[i][0]
            let y1 = points[i][1]
            for j in (i + 1)..<N {
                let x2 = points[j][0]
                let y2 = points[j][1]
                let dist = abs(x1 - x2) + abs(y1 - y2)
                adj[i, default: []].append([dist, j])
                adj[j, default: []].append([dist, i])
            }
        }

        var res = 0
        var visit: Set<Int> = []
        var minH: [(Int, Int)] = [(0, 0)]
        while visit.count < N {
            minH.sort { $0.0 < $1.0 }
            let curr = minH.removeFirst()
            let cost = curr.0
            let i = curr.1
            if visit.contains(i) {
                continue
            }
            res += cost
            visit.insert(i)
            for nei in adj[i, default: []] {
                let neiCost = nei[0]
                let neiIndex = nei[1]
                if !visit.contains(neiIndex) {
                    minH.append((neiCost, neiIndex))
                }
            }
        }
        return res
    }
}

